from pathlib import Path
import re
path = Path('/tmp/weooct2024all.csv')
lines = path.read_text(encoding='utf-8', errors='ignore').splitlines()
header = lines[0].split('\t')
# find index of 'Estimates Start After'
try:
    end_idx = header.index('Estimates Start After')
    header = header[:end_idx+1]
except ValueError:
    end_idx = len(header)-1
# build year indices
year_idx = {int(h): i for i, h in enumerate(header) if h.isdigit()}
print('years', min(year_idx), max(year_idx))
# function to parse data lines
results = {}
for line in lines[1:]:
    if not line or line.startswith(','):
        continue
    parts = line.split('\t')
    if len(parts) < 5:
        continue
    # trim parts to header length
    if len(parts) < len(header):
        parts += [''] * (len(header)-len(parts))
    else:
        parts = parts[:len(header)]
    country = parts[3]
    subj = parts[2]
    if country == 'Georgia' and subj in ('NGDP_R','NGDP_RPCH'):
        results[subj] = parts
        if len(results) == 2:
            break
print('found', results.keys())
for subj, parts in results.items():
    print(subj, {y: parts[year_idx[y]] for y in range(2000, 2005)})
